const page=await figma.getNodeByIdAsync('6:2'); await figma.setCurrentPageAsync(page);
const F1=await figma.getNodeByIdAsync('17:118'),F2=await figma.getNodeByIdAsync('18:132'),F3=await figma.getNodeByIdAsync('19:195'),F4=await figma.getNodeByIdAsync('19:352');
const nav=(dest,tr)=>[{trigger:{type:'ON_CLICK'},actions:[{type:'NODE',destinationId:dest.id,navigation:'NAVIGATE',transition:tr,preserveScrollPosition:false}]}];
const ease={type:'EASE_OUT'};
const out=[];
const b1=F1.children.find(n=>n.name==='Get Started');await b1.setReactionsAsync(nav(F2,{type:'MOVE_IN',direction:'TOP',matchLayers:false,easing:ease,duration:0.35}));out.push('01 GetStarted '+b1.id);
const sheet=F2.findOne(n=>n.name==='Sheet');
const b2=sheet.children.find(n=>n.name==='Get Started');await b2.setReactionsAsync(nav(F3,{type:'DISSOLVE',easing:ease,duration:0.3}));out.push('02 GetStarted '+b2.id);
const cancel=sheet.findOne(n=>n.name==='Cancel');await cancel.setReactionsAsync(nav(F1,{type:'MOVE_OUT',direction:'BOTTOM',matchLayers:false,easing:ease,duration:0.3}));out.push('02 Cancel '+cancel.id);
const hdr=F3.children.find(n=>n.name==='Header / Home');const av=hdr.findOne(n=>n.name==='Avatar');await av.setReactionsAsync(nav(F4,{type:'PUSH',direction:'RIGHT',matchLayers:false,easing:ease,duration:0.35}));out.push('03 Avatar '+av.id);
const hs=F4.findOne(n=>n.name==='Hotspot · back to 03_Home');await hs.setReactionsAsync(nav(F3,{type:'PUSH',direction:'LEFT',matchLayers:false,easing:ease,duration:0.35}));out.push('04 hotspot '+hs.id);
page.flowStartingPoints=[{nodeId:F1.id,name:'Payment Wallet · Onboarding'}];
for(const f of [F1,F2,F3,F4]) out.push(f.name+' '+f.id+' reactions:'+f.findAll(n=>n.reactions&&n.reactions.length>0).length);
return out.join('\n');

